//! Cross-language parity runner for the saved-login renewal port (cut gap G10).
//!
//! The manifest (generated by `tests/spec/renewal-parity.ts` from the TS
//! behaviour) describes sandboxes of FAKE credentials only — the same fake JWT
//! algorithm as `tests/unit/codex-auth/codex-renewal-fixtures.ts` — plus the
//! operation to run and the normalized TS answer. This module expands a case,
//! runs the Rust behaviour in a temporary root and produces the same normalized
//! answer, so `cargo test -p aac-renewal --features parity-fixtures` compares
//! against the checked-in TS goldens and the live checker compares TS and Rust
//! byte-for-byte on identical inputs. No provider calls, no real homes.

use crate::antigravity::{
    self, NativeCredential, RenewalProfileRef, RenewalRegistry, SavedProfileSnapshot,
    VerifiedIdentity,
};
use crate::claude::{self, ClaudeSignInRenewalReader, RenewalReaderDeps};
use crate::notes;
use crate::planner::{self, CodexRenewalEnvironment};
use crate::procscan::{CodexProcessSnapshot, ScanProcesses};
use crate::refresh::{CodexTokenFetch, FetchReply};
use crate::renewal::{self, CodexProfileRenewalOptions, CodexProfileRenewalProfileStatus};
use crate::service::{CodexProfileRenewalService, CodexProfileRenewalServiceDeps, CycleSeam};
use crate::types::{CodexRenewalReason, CodexRenewalState};
use base64::Engine;
use serde::Deserialize;
use serde_json::{Map, Value};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

/// The fixture clock, as the TS fixtures pin it: 2026-10-08T12:00:00Z.
pub const NOW: i64 = 1_791_460_800_000;
const DAY: i64 = 86_400_000;

/// One case's sandbox, operation and inputs.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct Case {
    /// Unique case name.
    pub name: String,
    /// Operation word: plan, dryRun, status, attempt, sequence, service,
    /// claude, claudeReader, note, sameGrant, liveToRenew, renewLive, entries.
    pub kind: String,
    /// The sandbox files and seams.
    #[serde(default)]
    pub sandbox: Sandbox,
    /// Operation inputs.
    #[serde(default)]
    pub inputs: Value,
}

/// The sandbox description: fake logins by spec, raw files, processes, history.
#[derive(Debug, Clone, Default, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Sandbox {
    /// Saved profiles, in registry order.
    #[serde(default)]
    pub profiles: Vec<ProfileSpec>,
    /// The live login under codexHome.
    #[serde(default)]
    pub live: Option<Login>,
    /// `.codex*` homes under the injected home folder.
    #[serde(default)]
    pub homes: Vec<HomeSpec>,
    /// Running Codex processes (home relative to the root, or null).
    #[serde(default)]
    pub processes: Vec<ProcessSpec>,
    /// The recorded history file content, when seeded.
    #[serde(default)]
    pub records: Option<Value>,
    /// CLIProxy token files.
    #[serde(default)]
    pub cliproxy: Vec<CliproxySpec>,
    /// A planted activation lock directory (busy case).
    #[serde(default)]
    pub lock: bool,
    /// Registered names without a profile folder (missing-login case).
    #[serde(default)]
    pub registry_only: Vec<String>,
    /// Raw files elsewhere under the root (process-home copies).
    #[serde(default)]
    pub extra_files: Vec<ExtraFile>,
}

/// One raw file under the sandbox root.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct ExtraFile {
    /// Relative path under the root.
    pub rel: String,
    /// The exact text.
    pub raw: String,
}

/// One saved profile: a name and its login (or raw bytes).
#[derive(Debug, Clone, serde::Deserialize)]
pub struct ProfileSpec {
    /// The registered name.
    pub name: String,
    /// The login content.
    pub login: Login,
}

/// A login: a fake-token spec, or raw file text.
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(untagged)]
pub enum Login {
    /// Raw file content (broken JSON, API-key files).
    Raw {
        /// The exact text.
        raw: String,
    },
    /// A fake credential spec.
    Spec(LoginSpec),
}

/// Deserialize a field that distinguishes absent (None) from explicit null
/// (Some(None)): the fixture specs omit markers with null, not by absence.
fn double_option<'de, D, T>(deserializer: D) -> Result<Option<Option<T>>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: serde::Deserialize<'de>,
{
    Ok(Some(Option::deserialize(deserializer)?))
}

/// The fake credential spec, mirroring the TS fixture's LoginSpec.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct LoginSpec {
    /// Account word (alpha/bravo/charlie) or an explicit account.
    pub account: Account,
    /// The fake refresh token marker.
    pub refresh: String,
    /// Unique label marking the fake signatures.
    pub label: String,
    /// Family session id; null omits both markers; absent defaults to sess-<label>.
    #[serde(default, deserialize_with = "double_option")]
    pub session: Option<Option<String>>,
    /// Original sign-in seconds; null omits; absent defaults to 1780000000.
    #[serde(default, deserialize_with = "double_option")]
    pub auth_time: Option<Option<f64>>,
    /// Access expiry ms; null omits exp; absent defaults to NOW + 7 days.
    #[serde(default, deserialize_with = "double_option")]
    pub access_exp: Option<Option<i64>>,
    /// last_refresh ISO; absent defaults to NOW - 3 days.
    #[serde(default)]
    pub last_refresh: Option<String>,
    /// Workspace claimed by the access token; absent uses the account's.
    #[serde(default)]
    pub access_account_id: Option<String>,
}

/// A fixture account.
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(untagged)]
pub enum Account {
    /// One of the three fixture accounts.
    Word(String),
    /// An explicit account.
    Explicit {
        /// Display email.
        email: String,
        /// Workspace id.
        account_id: String,
        /// Person id.
        user_id: String,
    },
}

impl Account {
    fn resolve(&self) -> (String, String, String) {
        match self {
            Self::Word(word) => match word.as_str() {
                "alpha" => (
                    "alpha@example.test".into(),
                    "acct-alpha".into(),
                    "user-alpha".into(),
                ),
                "bravo" => (
                    "bravo@example.test".into(),
                    "acct-bravo".into(),
                    "user-bravo".into(),
                ),
                "charlie" => (
                    "charlie@example.test".into(),
                    "acct-charlie".into(),
                    "user-charlie".into(),
                ),
                other => panic!("unknown fixture account {other}"),
            },
            Self::Explicit {
                email,
                account_id,
                user_id,
            } => (email.clone(), account_id.clone(), user_id.clone()),
        }
    }
}

/// One `.codex*` home under the home folder.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct HomeSpec {
    /// Relative home path, such as `.codex-t3/gmail`.
    pub rel: String,
    /// The login content.
    pub login: Login,
}

/// One running Codex process.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct ProcessSpec {
    /// CODEX_HOME relative to the root; null uses the nonexistent HOME.
    #[serde(default)]
    pub home: Option<String>,
    /// Process id.
    #[serde(default = "default_pid")]
    pub pid: u32,
}

fn default_pid() -> u32 {
    4242
}

/// One CLIProxy token file.
#[derive(Debug, Clone, serde::Deserialize)]
pub struct CliproxySpec {
    /// `auth` or `auth-paused`.
    pub folder: String,
    /// File name.
    pub name: String,
    /// The login content.
    pub login: Login,
}

fn b64url(value: &Value) -> String {
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(value.to_string())
}

fn jwt(payload: &Value, label: &str) -> String {
    let header = serde_json::json!({"alg": "RS256", "typ": "JWT"});
    let signature =
        base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(format!("FAKE-SIG-{label}"));
    format!("{}.{}.{}", b64url(&header), b64url(payload), signature)
}

/// The fake tokens, byte-identical to the TS fixture's makeTokens.
pub fn make_tokens(spec: &LoginSpec) -> (String, String, String) {
    let (email, account_id, user_id) = spec.account.resolve();
    let session = match &spec.session {
        Some(value) => value.clone(),
        None => Some(format!("sess-{}", spec.label)),
    };
    let auth_time = match spec.auth_time {
        Some(value) => value,
        None => Some(1_780_000_000.0),
    };
    let iat = NOW / 1000 - 3600;
    let mut id_payload = Map::new();
    id_payload.insert("email".into(), Value::String(email));
    id_payload.insert(
        "iss".into(),
        Value::String("https://auth.openai.com".into()),
    );
    id_payload.insert("sub".into(), Value::String(user_id.clone()));
    id_payload.insert("iat".into(), Value::Number(iat.into()));
    id_payload.insert("exp".into(), Value::Number((iat + 3600).into()));
    if let Some(session) = &session {
        id_payload.insert("sid".into(), Value::String(session.clone()));
    }
    if let Some(auth_time) = auth_time
        && let Some(n) = crate::jsnum::js_number(auth_time)
    {
        id_payload.insert("auth_time".into(), Value::Number(n));
    }
    let mut id_auth = Map::new();
    id_auth.insert(
        "chatgpt_account_id".into(),
        Value::String(account_id.clone()),
    );
    id_auth.insert("chatgpt_user_id".into(), Value::String(user_id.clone()));
    id_auth.insert("chatgpt_plan_type".into(), Value::String("pro".into()));
    id_payload.insert(crate::jwt::OPENAI_AUTH_CLAIM.into(), Value::Object(id_auth));
    let id_token = jwt(&Value::Object(id_payload), &format!("id-{}", spec.label));
    let access_exp = match spec.access_exp {
        Some(value) => value,
        None => Some(NOW + 7 * DAY),
    };
    let mut access_payload = Map::new();
    access_payload.insert("iat".into(), Value::Number(iat.into()));
    if let Some(exp) = access_exp {
        access_payload.insert("exp".into(), Value::Number((exp / 1000).into()));
    }
    if let Some(session) = &session {
        access_payload.insert("session_id".into(), Value::String(session.clone()));
    }
    let mut access_auth = Map::new();
    access_auth.insert(
        "chatgpt_account_id".into(),
        Value::String(spec.access_account_id.clone().unwrap_or(account_id.clone())),
    );
    access_auth.insert("chatgpt_user_id".into(), Value::String(user_id));
    access_payload.insert(
        crate::jwt::OPENAI_AUTH_CLAIM.into(),
        Value::Object(access_auth),
    );
    let access_token = jwt(
        &Value::Object(access_payload),
        &format!("access-{}", spec.label),
    );
    (id_token, access_token, spec.refresh.clone())
}

/// The fake auth file bytes, byte-identical to the TS fixture's loginBuffer.
pub fn login_buffer(spec: &LoginSpec) -> Vec<u8> {
    let (id_token, access_token, refresh_token) = make_tokens(spec);
    let (_, account_id, _) = spec.account.resolve();
    let last_refresh = spec
        .last_refresh
        .clone()
        .unwrap_or_else(|| crate::jsnum::iso(NOW - 3 * DAY).unwrap_or_default());
    let mut tokens = Map::new();
    tokens.insert("id_token".into(), Value::String(id_token));
    tokens.insert("access_token".into(), Value::String(access_token));
    tokens.insert("refresh_token".into(), Value::String(refresh_token));
    tokens.insert("account_id".into(), Value::String(account_id));
    let mut doc = Map::new();
    doc.insert("OPENAI_API_KEY".into(), Value::Null);
    doc.insert("auth_mode".into(), Value::String("chatgpt".into()));
    doc.insert("last_refresh".into(), Value::String(last_refresh));
    doc.insert("tokens".into(), Value::Object(tokens));
    let mut extra = Map::new();
    extra.insert("kept".into(), Value::Bool(true));
    doc.insert("unknown_extra".into(), Value::Object(extra));
    serde_json::to_string_pretty(&Value::Object(doc))
        .unwrap_or_default()
        .into_bytes()
}

fn login_bytes(login: &Login) -> Vec<u8> {
    match login {
        Login::Raw { raw } => raw.clone().into_bytes(),
        Login::Spec(spec) => login_buffer(spec),
    }
}

/// A prepared sandbox in a temporary root.
pub struct Prepared {
    /// The temporary root (kept alive for the case's duration).
    pub root: tempfile::TempDir,
    /// The CCS root (`<root>/.ccs`).
    pub ccs_dir: PathBuf,
    /// The shared Codex home (`<root>/shared-codex`).
    pub codex_home: PathBuf,
    /// The injected home folder (`<root>/home`).
    pub home_dir: PathBuf,
    /// The environment the case runs with.
    pub env: CodexRenewalEnvironment,
    /// The clock the case advances.
    pub clock: Arc<Mutex<i64>>,
}

fn write_private(file: &Path, bytes: &[u8]) {
    if let Some(parent) = file.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let temporary = file.with_extension("fixture");
    let _ = std::fs::write(&temporary, bytes);
    let _ = std::fs::rename(&temporary, file);
}

/// Expand a sandbox into a temporary root, as the TS RenewalSandbox does.
pub fn prepare(case: &Case) -> Prepared {
    let root = tempfile::tempdir().expect("tempdir");
    let ccs_dir = root.path().join(".ccs");
    let codex_home = root.path().join("shared-codex");
    let home_dir = root.path().join("home");
    std::fs::create_dir_all(&codex_home).expect("codex home");
    std::fs::create_dir_all(&home_dir).expect("home dir");
    std::fs::create_dir_all(&ccs_dir).expect("ccs dir");
    let instances = ccs_dir.join("codex-instances");
    let mut registry = String::from("version: '1.0'\ndefault: null\nprofiles:\n");
    for profile in &case.sandbox.profiles {
        let dir = instances.join(&profile.name);
        std::fs::create_dir_all(&dir).expect("profile dir");
        write_private(&dir.join("auth.json"), &login_bytes(&profile.login));
        registry.push_str(&format!(
            "  {}:\n    type: codex\n    created: '2026-10-01T00:00:00.000Z'\n    last_used: null\n",
            profile.name
        ));
    }
    for name in &case.sandbox.registry_only {
        registry.push_str(&format!(
            "  {}:\n    type: codex\n    created: '2026-10-01T00:00:00.000Z'\n    last_used: null\n",
            name
        ));
    }
    if case.sandbox.profiles.is_empty() && case.sandbox.registry_only.is_empty() {
        registry.push_str("  {}\n");
    }
    std::fs::write(ccs_dir.join("codex-profiles.yaml"), registry).expect("registry");
    if let Some(live) = &case.sandbox.live {
        write_private(&codex_home.join("auth.json"), &login_bytes(live));
    }
    for home in &case.sandbox.homes {
        let dir = home_dir.join(&home.rel);
        std::fs::create_dir_all(&dir).expect("home");
        write_private(&dir.join("auth.json"), &login_bytes(&home.login));
    }
    for file in &case.sandbox.cliproxy {
        let dir = ccs_dir.join("cliproxy").join(&file.folder);
        std::fs::create_dir_all(&dir).expect("cliproxy dir");
        write_private(&dir.join(&file.name), &login_bytes(&file.login));
    }
    if let Some(records) = &case.sandbox.records {
        let text = format!(
            "{}\n",
            serde_json::to_string_pretty(records).unwrap_or_default()
        );
        write_private(&ccs_dir.join("codex-renewal-status.json"), text.as_bytes());
    }
    if case.sandbox.lock {
        std::fs::create_dir(codex_home.join(".ccs-activation.lock")).expect("lock");
    }
    for file in &case.sandbox.extra_files {
        let path = root.path().join(&file.rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("extra dir");
        }
        std::fs::write(&path, file.raw.as_bytes()).expect("extra file");
    }
    let clock = Arc::new(Mutex::new(NOW));
    let processes: Vec<CodexProcessSnapshot> = case
        .sandbox
        .processes
        .iter()
        .map(|process| {
            let mut env = HashMap::new();
            match &process.home {
                Some(home) => {
                    env.insert(
                        "CODEX_HOME".to_owned(),
                        root.path().join(home).to_string_lossy().into_owned(),
                    );
                }
                None => {
                    env.insert("HOME".to_owned(), "/nonexistent-home".to_owned());
                }
            }
            CodexProcessSnapshot {
                pid: process.pid,
                ppid: 1,
                start_time: "100".into(),
                state: "S".into(),
                args: vec!["/usr/local/bin/codex".into(), "app-server".into()],
                exe: "/usr/local/bin/codex".into(),
                cwd: "/".into(),
                env,
            }
        })
        .collect();
    let scan_mode = case
        .inputs
        .get("scan")
        .and_then(Value::as_str)
        .unwrap_or("ok")
        .to_owned();
    let scan: ScanProcesses = Arc::new(move || match scan_mode.as_str() {
        "fail" => Err(()),
        "unavailable" => Ok(None),
        _ => Ok(Some(processes.clone())),
    });
    let env = CodexRenewalEnvironment {
        ccs_dir: ccs_dir.clone(),
        codex_home: Some(codex_home.clone()),
        home_dir: Some(home_dir.clone()),
        extra_codex_homes: Vec::new(),
        scan_processes: Some(scan),
        list_profiles: None,
        renew_within_ms: case.inputs.get("renewWithinMs").and_then(Value::as_f64),
    };
    Prepared {
        root,
        ccs_dir,
        codex_home,
        home_dir,
        env,
        clock,
    }
}

fn env_map(inputs: &Value) -> Option<HashMap<String, String>> {
    let map = inputs.get("env")?.as_object()?;
    Some(
        map.iter()
            .map(|(k, v)| (k.clone(), v.as_str().unwrap_or_default().to_owned()))
            .collect(),
    )
}

thread_local! {
    static LOG_SINK: Arc<Mutex<Vec<Value>>> = Arc::new(Mutex::new(Vec::new()));
}

fn options(prepared: &Prepared, case: &Case) -> CodexProfileRenewalOptions {
    let clock = Arc::clone(&prepared.clock);
    let mut options = CodexProfileRenewalOptions {
        env: prepared.env.clone(),
        env_map: Some(env_map(&case.inputs).unwrap_or_default()),
        now: Arc::new(move || *clock.lock().expect("clock")),
        random: Arc::new(|| 0.5),
        sleep: Arc::new(|_ms| Box::pin(async move {})),
        ..Default::default()
    };
    // The TS sandbox always records the outcome trail; mirror it.
    let sink = LOG_SINK.with(Arc::clone);
    options.log = Some(Arc::new(move |level, event, message, context| {
        let mut entry = Map::new();
        entry.insert("level".into(), Value::String(level.into()));
        entry.insert("event".into(), Value::String(event.into()));
        entry.insert("message".into(), Value::String(message.into()));
        entry.insert("context".into(), context.clone());
        sink.lock().expect("logs").push(Value::Object(entry));
    }));
    options
}

/// One fake fetch response: a status/body pair or a transport error.
#[derive(Debug, Clone, serde::Deserialize)]
#[serde(untagged)]
pub enum FakeResponse {
    /// A transport failure.
    Error {
        /// `timeout` or `network`.
        error: String,
    },
    /// A successful refresh generated from a spec (no token text in goldens).
    Refreshed {
        /// The login spec whose rotated tokens answer.
        spec: LoginSpec,
        /// Whether the body carries the id token (default true).
        #[serde(default)]
        include_id: Option<bool>,
        /// Whether the body carries the rotated refresh token (default true).
        #[serde(default)]
        include_refresh: Option<bool>,
    },
    /// An HTTP response with an explicit body.
    Response {
        /// HTTP status.
        status: u16,
        /// The body: a JSON value or raw text.
        body: Value,
    },
}

impl FakeResponse {
    fn reply(&self) -> FetchReply {
        match self {
            Self::Error { error } if error == "timeout" => FetchReply::Timeout,
            Self::Error { .. } => FetchReply::Network,
            Self::Refreshed {
                spec,
                include_id,
                include_refresh,
            } => FetchReply::Response {
                status: 200,
                text: refreshed_body(
                    spec,
                    include_id.unwrap_or(true),
                    include_refresh.unwrap_or(true),
                )
                .to_string(),
            },
            Self::Response { status, body } => FetchReply::Response {
                status: *status,
                text: match body {
                    Value::String(text) => text.clone(),
                    other => other.to_string(),
                },
            },
        }
    }
}

/// A successful refresh body for a spec (the TS fixture's refreshedBody).
pub fn refreshed_body(spec: &LoginSpec, include_id: bool, include_refresh: bool) -> Value {
    let (id_token, access_token, refresh_token) = make_tokens(spec);
    let mut out = Map::new();
    if include_id {
        out.insert("id_token".into(), Value::String(id_token));
    }
    out.insert("access_token".into(), Value::String(access_token));
    if include_refresh {
        out.insert("refresh_token".into(), Value::String(refresh_token));
    }
    Value::Object(out)
}

struct FetchScript {
    responses: Mutex<Vec<FakeResponse>>,
    by_token: Vec<(String, FakeResponse)>,
    repeat_last: bool,
    calls: Mutex<Vec<Value>>,
    actions: Mutex<Vec<Value>>,
    prepared_root: PathBuf,
}

impl FetchScript {
    fn from_inputs(inputs: &Value, root: &Path) -> Self {
        let fetch = inputs.get("fetch").cloned().unwrap_or(Value::Null);
        let responses: Vec<FakeResponse> = fetch
            .get("responses")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| serde_json::from_value(item.clone()).ok())
                    .collect()
            })
            .unwrap_or_default();
        let by_token = fetch
            .get("byToken")
            .and_then(Value::as_object)
            .map(|map| {
                map.iter()
                    .filter_map(|(token, item)| {
                        serde_json::from_value(item.clone())
                            .ok()
                            .map(|response| (token.clone(), response))
                    })
                    .collect()
            })
            .unwrap_or_default();
        Self {
            responses: Mutex::new(responses),
            by_token,
            repeat_last: fetch
                .get("repeatLast")
                .and_then(Value::as_bool)
                .unwrap_or(false),
            calls: Mutex::new(Vec::new()),
            actions: Mutex::new(Vec::new()),
            prepared_root: root.to_path_buf(),
        }
    }

    fn seam(self: &Arc<Self>) -> CodexTokenFetch {
        let script = Arc::clone(self);
        Arc::new(move |call| {
            let script = Arc::clone(&script);
            Box::pin(async move {
                let body: Value = serde_json::from_str(&call.body).unwrap_or(Value::Null);
                let mut call_record = Map::new();
                call_record.insert("url".into(), Value::String(call.url.clone()));
                call_record.insert("body".into(), body.clone());
                script
                    .calls
                    .lock()
                    .expect("calls")
                    .push(Value::Object(call_record));
                // Actions run inside the fetch, before the answer (the TS CAS test).
                let actions: Vec<Value> =
                    std::mem::take(&mut *script.actions.lock().expect("actions"));
                for action in actions {
                    if let Some(write) = action.get("writeProfile") {
                        let name = write
                            .get("name")
                            .and_then(Value::as_str)
                            .unwrap_or_default();
                        let login: Login = serde_json::from_value(
                            write.get("login").cloned().unwrap_or(Value::Null),
                        )
                        .expect("login spec");
                        let file = script
                            .prepared_root
                            .join(".ccs")
                            .join("codex-instances")
                            .join(name)
                            .join("auth.json");
                        write_private(&file, &login_bytes(&login));
                    }
                }
                let token = body
                    .get("refresh_token")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_owned();
                let exact = script.by_token.iter().find(|(key, _)| key == &token);
                let wildcard = script.by_token.iter().find(|(key, _)| key == "*");
                let mut responses = script.responses.lock().expect("responses");
                if let Some((_, response)) = exact.or(wildcard) {
                    return response.reply();
                }
                if responses.is_empty() {
                    return FetchReply::Network;
                }
                let response = if script.repeat_last && responses.len() == 1 {
                    responses[0].clone()
                } else {
                    responses.remove(0)
                };
                response.reply()
            })
        })
    }
}

/// Normalize an answer: sandbox paths become `<root>/...` with forward slashes.
pub fn normalize_answer(value: &Value, root: &Path) -> Value {
    let root_text = root.to_string_lossy().into_owned();
    let root_slash = root_text.replace('\\', "/");
    match value {
        Value::String(text) => {
            let replaced = text
                .replace(&root_text, "<root>")
                .replace(&root_slash, "<root>")
                .replace('\\', "/");
            Value::String(replaced)
        }
        Value::Array(items) => Value::Array(
            items
                .iter()
                .map(|item| normalize_answer(item, root))
                .collect(),
        ),
        Value::Object(map) => {
            let mut out = Map::new();
            for (key, item) in map {
                out.insert(key.clone(), normalize_answer(item, root));
            }
            Value::Object(out)
        }
        other => other.clone(),
    }
}

fn normalize_auth(text: &str) -> String {
    let Ok(mut value) = serde_json::from_str::<Value>(text) else {
        return text.to_owned();
    };
    if let Some(tokens) = value.get_mut("tokens").and_then(Value::as_object_mut) {
        for (key, marker) in [
            ("id_token", "<id_token>"),
            ("access_token", "<access_token>"),
            ("refresh_token", "<refresh_token>"),
        ] {
            if tokens.get(key).is_some_and(Value::is_string) {
                tokens.insert(key.into(), Value::String(marker.into()));
            }
        }
    }
    serde_json::to_string_pretty(&value).unwrap_or_else(|_| text.to_owned())
}

fn normalize_status(text: &str) -> String {
    let Ok(mut value) = serde_json::from_str::<Value>(text) else {
        return text.to_owned();
    };
    if let Some(profiles) = value.get_mut("profiles").and_then(Value::as_object_mut) {
        for (_, record) in profiles.iter_mut() {
            if let Some(record) = record.as_object_mut()
                && record.contains_key("authVersion")
            {
                record.insert("authVersion".into(), Value::String("<version>".into()));
            }
        }
    }
    format!(
        "{}\n",
        serde_json::to_string_pretty(&value).unwrap_or_else(|_| text.to_owned())
    )
}

fn visit_files(dir: &Path, root: &Path, out: &mut Map<String, Value>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(meta) = std::fs::symlink_metadata(&path) else {
            continue;
        };
        if meta.is_dir() {
            visit_files(&path, root, out);
        } else if meta.is_file() {
            let rel = path
                .strip_prefix(root)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/");
            if rel.ends_with("codex-profiles.yaml") || rel.starts_with(".ccs/logs/") {
                continue;
            }
            let Ok(bytes) = std::fs::read(&path) else {
                continue;
            };
            let text = String::from_utf8_lossy(&bytes).into_owned();
            let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
            let normalized = if name == "auth.json" {
                normalize_auth(&text)
            } else if name == "codex-renewal-status.json" {
                normalize_status(&text)
            } else {
                text
            };
            out.insert(rel, Value::String(normalized));
        }
    }
}

/// The sandbox's renewal-relevant files, normalized for comparison: auth files
/// with token values replaced by markers, the history with versions replaced.
pub fn files_map(root: &Path) -> Value {
    let mut out = Map::new();
    visit_files(root, root, &mut out);
    out.sort_keys();
    Value::Object(out)
}

fn profile_status(
    state: CodexRenewalState,
    reason: CodexRenewalReason,
    access_expires_at: Option<String>,
) -> CodexProfileRenewalProfileStatus {
    CodexProfileRenewalProfileStatus {
        name: "gmail".into(),
        state,
        reason,
        message: reason.message(),
        last_renewed_at: None,
        last_attempt_at: None,
        last_outcome: None,
        next_attempt_at: None,
        access_expires_at,
    }
}

/// Run one case and produce its normalized answer.
pub async fn run_case(case: &Case) -> Value {
    // Each case gets a fresh log trail (the sink is thread-local).
    LOG_SINK.with(|logs| logs.lock().expect("logs").clear());
    let prepared = prepare(case);
    let root = prepared.root.path().to_path_buf();
    let mut options = options(&prepared, case);
    let answer = match case.kind.as_str() {
        "plan" => {
            let snapshot =
                planner::collect_codex_renewal_snapshot(&prepared.env, None).expect("snapshot");
            let now = *prepared.clock.lock().expect("clock");
            let entries = planner::plan_codex_profile_renewals(&snapshot, now);
            let mut out = Map::new();
            for entry in entries {
                out.insert(entry.name.clone(), entry.to_json());
            }
            Value::Object(out)
        }
        "dryRun" => renewal::dry_run_codex_profile_renewal(&options)
            .expect("dry run")
            .to_json(),
        "status" => renewal::get_codex_profile_renewal_status(&options)
            .expect("status")
            .to_json(),
        "attempt" => {
            let script = Arc::new(FetchScript::from_inputs(&case.inputs, &root));
            if let Some(actions) = case.inputs.get("actions").and_then(Value::as_array) {
                *script.actions.lock().expect("actions") = actions.clone();
            }
            options.fetch = Some(script.seam());
            let name = case
                .inputs
                .get("name")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let attempt = renewal::renew_codex_profile(name, &options).await;
            let mut out = Map::new();
            out.insert("attempt".into(), attempt.to_json());
            out.insert(
                "calls".into(),
                Value::Array(script.calls.lock().expect("calls").clone()),
            );
            out.insert("files".into(), files_map(&root));
            Value::Object(out)
        }
        "sequence" => {
            let script = Arc::new(FetchScript::from_inputs(&case.inputs, &root));
            options.fetch = Some(script.seam());
            let steps = case
                .inputs
                .get("steps")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let mut cycles = Vec::new();
            for step in steps {
                if let Some(advance) = step.get("advanceMs").and_then(Value::as_i64) {
                    *prepared.clock.lock().expect("clock") += advance;
                }
                if let Some(actions) = step.get("actions").and_then(Value::as_array) {
                    for action in actions {
                        if let Some(write) = action.get("writeProfile") {
                            let name = write
                                .get("name")
                                .and_then(Value::as_str)
                                .unwrap_or_default();
                            let login: Login = serde_json::from_value(
                                write.get("login").cloned().unwrap_or(Value::Null),
                            )
                            .expect("login spec");
                            let file = prepared
                                .ccs_dir
                                .join("codex-instances")
                                .join(name)
                                .join("auth.json");
                            write_private(&file, &login_bytes(&login));
                        }
                    }
                }
                let cycle = renewal::renew_due_codex_profiles(&options)
                    .await
                    .expect("cycle");
                cycles.push(cycle.to_json());
            }
            let status = renewal::get_codex_profile_renewal_status(&options).expect("status");
            let logs = LOG_SINK.with(|logs| logs.lock().expect("logs").clone());
            let mut out = Map::new();
            out.insert("cycles".into(), Value::Array(cycles));
            out.insert("status".into(), status.to_json());
            out.insert(
                "calls".into(),
                Value::Array(script.calls.lock().expect("calls").clone()),
            );
            out.insert("logs".into(), Value::Array(logs));
            out.insert("files".into(), files_map(&root));
            Value::Object(out)
        }
        "service" => run_service_case(case, &prepared).await,
        "claude" => {
            let now = case
                .inputs
                .get("now")
                .and_then(Value::as_i64)
                .unwrap_or(NOW);
            let text = match case.inputs.get("text") {
                Some(Value::String(text)) => text.clone(),
                _ => case
                    .inputs
                    .get("doc")
                    .map(|doc| doc.to_string())
                    .unwrap_or_default(),
            };
            claude::parse_claude_signin_renewal(&text, now)
                .map(|parsed| parsed.to_json())
                .unwrap_or(Value::Null)
        }
        "claudeReader" => {
            let now = case
                .inputs
                .get("now")
                .and_then(Value::as_i64)
                .unwrap_or(NOW);
            let folder = case
                .inputs
                .get("folder")
                .and_then(Value::as_str)
                .map(PathBuf::from);
            let text = case
                .inputs
                .get("text")
                .and_then(Value::as_str)
                .map(str::to_owned);
            let reader = ClaudeSignInRenewalReader::new(
                prepared.ccs_dir.clone(),
                RenewalReaderDeps {
                    folder: Some(Arc::new(move || folder.clone())),
                    read_file: text.map(|text| {
                        Arc::new(move |_file: &Path| Ok(text.clone())) as claude::ReadFileSeam
                    }),
                    now: Some(Arc::new(move || now)),
                },
            );
            reader
                .read()
                .map(|parsed| parsed.to_json())
                .unwrap_or(Value::Null)
        }
        "note" => {
            let state = case
                .inputs
                .get("state")
                .and_then(Value::as_str)
                .unwrap_or("ok");
            let reason = case
                .inputs
                .get("reason")
                .and_then(Value::as_str)
                .unwrap_or("fresh");
            let state = match state {
                "ok" => CodexRenewalState::Ok,
                "due" => CodexRenewalState::Due,
                "renewing" => CodexRenewalState::Renewing,
                "retrying" => CodexRenewalState::Retrying,
                "failed" => CodexRenewalState::Failed,
                _ => CodexRenewalState::Skipped,
            };
            let reason = CodexRenewalReason::from_code(reason).expect("reason");
            let expires = case
                .inputs
                .get("accessExpiresAt")
                .and_then(Value::as_str)
                .map(str::to_owned);
            let needs_reauth = case
                .inputs
                .get("needsReauth")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let now = case
                .inputs
                .get("now")
                .and_then(Value::as_i64)
                .unwrap_or(NOW);
            notes::codex_renewal_note(needs_reauth, &profile_status(state, reason, expires), now)
                .map(|note| note.to_json())
                .unwrap_or(Value::Null)
        }
        "sameGrant" => {
            let left = credential_from(&case.inputs["left"]);
            let right = credential_from(&case.inputs["right"]);
            Value::Bool(antigravity::same_grant(&left, &right))
        }
        "liveToRenew" => run_live_to_renew(case).await,
        "renewLive" => run_renew_live(case).await,
        "entries" => {
            let fail = case
                .inputs
                .get("fail")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let status = if fail {
                Err(())
            } else {
                renewal::get_codex_profile_renewal_status(&options).map_err(|_| ())
            };
            notes::entries_to_json(&notes::codex_renewal_entries(status))
        }
        other => panic!("unknown case kind {other}"),
    };
    normalize_answer(&answer, &root)
}

async fn run_service_case(case: &Case, prepared: &Prepared) -> Value {
    let clock = Arc::clone(&prepared.clock);
    let env = env_map(&case.inputs).unwrap_or_default();
    let fail = case
        .inputs
        .get("failCycle")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let runner: CycleSeam = if fail {
        Arc::new(|_options| Box::pin(async move { Err(()) }))
    } else {
        Arc::new(|_options| {
            Box::pin(async move {
                Ok(renewal::CodexRenewalCycle {
                    started_at: crate::jsnum::iso(NOW).unwrap_or_default(),
                    finished_at: crate::jsnum::iso(NOW).unwrap_or_default(),
                    enabled: true,
                    plans: Vec::new(),
                    attempts: Vec::new(),
                    retry_at: None,
                })
            })
        })
    };
    let service = CodexProfileRenewalService::new(CodexProfileRenewalServiceDeps {
        ccs_dir: prepared.ccs_dir.clone(),
        env_map: Some(env),
        now: Arc::new(move || *clock.lock().expect("clock")),
        random: Arc::new(|| 0.5),
        renewal: options(prepared, case),
        run_cycle: Some(runner),
    });
    let steps = case
        .inputs
        .get("steps")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut statuses = Vec::new();
    for step in steps {
        match step.as_str().unwrap_or_default() {
            "start" => service.start(),
            "stop" => service.stop(),
            "status" => statuses.push(service.get_status().await.to_json()),
            "runCycle" => {
                let _ = service.run_cycle().await;
            }
            other => panic!("unknown service step {other}"),
        }
    }
    Value::Array(statuses)
}

fn credential_from(value: &Value) -> NativeCredential {
    if value.get("empty").and_then(Value::as_bool).unwrap_or(false) {
        return NativeCredential {
            format: "native".into(),
            bytes: Vec::new(),
        };
    }
    if value
        .get("oversized")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return NativeCredential {
            format: "native".into(),
            bytes: vec![b'x'; 16_385],
        };
    }
    if let Some(raw) = value.get("raw").and_then(Value::as_str) {
        return NativeCredential {
            format: "native".into(),
            bytes: raw.as_bytes().to_vec(),
        };
    }
    let refresh = value
        .get("refresh")
        .and_then(Value::as_str)
        .unwrap_or_default();
    NativeCredential {
        format: "native".into(),
        bytes: serde_json::json!({"token": {"refresh_token": refresh}})
            .to_string()
            .into_bytes(),
    }
}

fn identity_from(value: &Value) -> VerifiedIdentity {
    VerifiedIdentity {
        email: value
            .get("email")
            .and_then(Value::as_str)
            .unwrap_or("a@example.com")
            .to_owned(),
        subject: value
            .get("subject")
            .and_then(Value::as_str)
            .unwrap_or("sub-1")
            .to_owned(),
        plan: value.get("plan").and_then(Value::as_str).map(str::to_owned),
        verified_at: value
            .get("verifiedAt")
            .and_then(Value::as_str)
            .unwrap_or("2026-10-08T12:00:00.000Z")
            .to_owned(),
        source: value
            .get("source")
            .and_then(Value::as_str)
            .unwrap_or("provider-userinfo")
            .to_owned(),
    }
}

struct CaseLive {
    exists: bool,
    credential: Mutex<Option<NativeCredential>>,
    validate: Option<VerifiedIdentity>,
    install_ok: bool,
}

impl antigravity::LiveLoginAccess for CaseLive {
    fn exists(&self) -> Result<bool, ()> {
        Ok(self.exists)
    }
    fn read(
        &self,
    ) -> std::pin::Pin<
        Box<dyn std::future::Future<Output = Result<NativeCredential, ()>> + Send + '_>,
    > {
        Box::pin(async move { self.credential.lock().expect("live").clone().ok_or(()) })
    }
    fn validate(
        &self,
        _credential: NativeCredential,
    ) -> std::pin::Pin<
        Box<dyn std::future::Future<Output = Result<VerifiedIdentity, ()>> + Send + '_>,
    > {
        let result = self.validate.clone().ok_or(());
        Box::pin(async move { result })
    }
    fn install(
        &self,
        credential: NativeCredential,
        _expected: String,
    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<(), ()>> + Send + '_>> {
        let ok = self.install_ok;
        Box::pin(async move {
            if ok {
                *self.credential.lock().expect("live") = Some(credential);
                Ok(())
            } else {
                Err(())
            }
        })
    }
}

struct CaseRegistry {
    revision: Option<String>,
    saved: Option<NativeCredential>,
    restore_ok: bool,
}

impl RenewalRegistry for CaseRegistry {
    fn saved_revision(&self, _profile_id: &str) -> Option<String> {
        self.revision.clone()
    }
    fn read_credential(&self, _profile_id: &str) -> Result<NativeCredential, ()> {
        self.saved.clone().ok_or(())
    }
    fn restore_profile(&self, _snapshot: &SavedProfileSnapshot) -> Result<(), ()> {
        if self.restore_ok { Ok(()) } else { Err(()) }
    }
}

async fn run_live_to_renew(case: &Case) -> Value {
    let inputs = &case.inputs;
    let credential = inputs
        .get("credential")
        .filter(|v| !v.is_null())
        .map(credential_from);
    let fingerprint = credential.as_ref().map(antigravity::credential_fingerprint);
    let validate = match inputs.get("validate") {
        Some(Value::Null) | None => None,
        Some(Value::String(word)) if word == "error" => None,
        Some(value) => Some(identity_from(value)),
    };
    let live = CaseLive {
        exists: inputs
            .get("exists")
            .and_then(Value::as_bool)
            .unwrap_or(true),
        credential: Mutex::new(credential),
        validate,
        install_ok: true,
    };
    let revision = if inputs
        .get("matchSaved")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        fingerprint.clone()
    } else {
        None
    };
    let registry = CaseRegistry {
        revision,
        saved: inputs
            .get("saved")
            .filter(|v| !v.is_null())
            .map(credential_from),
        restore_ok: true,
    };
    let identity = identity_from(inputs.get("profile").unwrap_or(&Value::Null));
    let profile = RenewalProfileRef {
        id: "p1".into(),
        identity_key: antigravity::identity_key(
            &antigravity::checked_identity(&identity).expect("identity"),
        )
        .expect("key"),
    };
    match antigravity::live_login_to_renew(&live, &registry, &profile).await {
        Some(_) => Value::String("<fp>".into()),
        None => Value::Null,
    }
}

async fn run_renew_live(case: &Case) -> Value {
    let inputs = &case.inputs;
    let new_credential = credential_from(inputs.get("newCredential").unwrap_or(&Value::Null));
    let live_after = inputs
        .get("liveAfter")
        .filter(|v| !v.is_null())
        .map(credential_from);
    let live = CaseLive {
        exists: true,
        credential: Mutex::new(live_after),
        validate: None,
        install_ok: inputs
            .get("installOk")
            .and_then(Value::as_bool)
            .unwrap_or(true),
    };
    let registry = CaseRegistry {
        revision: None,
        saved: None,
        restore_ok: inputs
            .get("restoreOk")
            .and_then(Value::as_bool)
            .unwrap_or(true),
    };
    let snapshot = SavedProfileSnapshot {
        index: 0,
        record: serde_json::json!({"id": "p1"}),
    };
    let save_ok = inputs
        .get("saveOk")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let result = antigravity::renew_live_login(
        &live,
        &registry,
        &snapshot,
        new_credential,
        "fp-old",
        || if save_ok { Ok(()) } else { Err(()) },
    )
    .await;
    match result {
        Ok(outcome) => Value::String(outcome.word().into()),
        Err(()) => Value::String("save_error".into()),
    }
}

/// The checked-in golden manifest.
#[derive(Debug, serde::Deserialize)]
pub struct Manifest {
    /// Format version.
    pub version: u64,
    /// The cases, with their expected normalized TS answers.
    pub cases: Vec<GoldenCase>,
}

/// One case plus its expected answer.
#[derive(Debug, serde::Deserialize)]
pub struct GoldenCase {
    /// The case definition.
    #[serde(flatten)]
    pub case: Case,
    /// The normalized TS answer.
    #[serde(default)]
    pub expected: Value,
}

/// Run every golden case and return (name, ok, detail) per case.
pub async fn run_goldens(manifest: &Manifest) -> Vec<(String, bool, String)> {
    let mut results = Vec::new();
    for golden in &manifest.cases {
        let answer = run_case(&golden.case).await;
        let ok = serde_json::to_string_pretty(&answer).unwrap_or_default()
            == serde_json::to_string_pretty(&golden.expected).unwrap_or_default();
        let detail = if ok {
            String::new()
        } else {
            format!(
                "expected:\n{}\nactual:\n{}",
                serde_json::to_string_pretty(&golden.expected).unwrap_or_default(),
                serde_json::to_string_pretty(&answer).unwrap_or_default()
            )
        };
        results.push((golden.case.name.clone(), ok, detail));
    }
    results
}
